package com.nextfeet.nextfeet.repository; import java.util.*; import org.springframework.jdbc.core.*; import org.springframework.stereotype.Repository; import com.nextfeet.nextfeet.model.Oferta; @Repository public class OfertaRepository implements OfertaDAO {private final JdbcTemplate db; public OfertaRepository(JdbcTemplate db){this.db=db;} private final RowMapper<Oferta> map=(r,n)->{Oferta o=new Oferta();o.setId(r.getInt("id"));o.setNombre(r.getString("nombre"));o.setTipo(r.getString("tipo"));o.setValor(r.getBigDecimal("valor"));o.setFechaInicio(r.getDate("fecha_inicio")==null?null:r.getDate("fecha_inicio").toLocalDate());o.setFechaFin(r.getDate("fecha_fin")==null?null:r.getDate("fecha_fin").toLocalDate());o.setEstado(r.getString("estado"));return o;}; public List<Oferta> listar(){return db.query("select * from oferta order by id desc",map);} public void crear(Oferta o){db.update("insert into oferta(nombre,tipo,valor,fecha_inicio,fecha_fin,estado) values(?,?,?,?,?,?)",o.getNombre(),o.getTipo(),o.getValor(),o.getFechaInicio(),o.getFechaFin(),"ACTIVO");} public void actualizar(Oferta o){db.update("update oferta set nombre=?,tipo=?,valor=?,fecha_inicio=?,fecha_fin=? where id=?",o.getNombre(),o.getTipo(),o.getValor(),o.getFechaInicio(),o.getFechaFin(),o.getId());} public void desactivar(Integer id){db.update("update oferta set estado='INACTIVO' where id=?",id);}}